/**
 * nav-stats.js — adds Q/A counters to left nav.
 * Phase 3.6: shows count of questions per section in nav subtitles.
 * Data is generated by tools/build_trainer.py where possible; fallback is static map.
 */
(function () {
  // Fallback static counts derived from latest build (831 total)
  const COUNTS = {
    "Senior Stack": 180,
    "MLOps": 45,
    "Python": 80,
    "Go": 90,
    "Linux": 35,
    "Observability": 40,
    "Git": 45,
    "Docker": 35,
    "Kubernetes": 45,
    "GitOps": 35,
    "Terraform": 15,
    "Ansible": 15
  };

  function inject() {
    try {
      const nav = document.querySelector(".md-nav--primary");
      if (!nav) return;
      // Find nav titles that correspond to major sections and append badge
      nav.querySelectorAll(".md-nav__item--nested > .md-nav__link").forEach(link => {
        const txt = link.textContent.trim();
        // Avoid double injection
        if (link.querySelector(".nav-stat")) return;
        for (const [key, cnt] of Object.entries(COUNTS)) {
          if (txt.includes(key) && cnt) {
            const badge = document.createElement("span");
            badge.className = "nav-stat";
            badge.textContent = cnt + " Q/A";
            link.appendChild(badge);
            break;
          }
        }
      });
    } catch (e) { console.warn("nav-stats", e); }
  }

  if (typeof document$ !== "undefined" && document$.subscribe) {
    document$.subscribe(inject);
  } else {
    document.addEventListener("DOMContentLoaded", inject);
  }
  if (document.readyState !== "loading") inject();
})();
